# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OKULUN BÖLÜMLERİ (أَقْسَامُ الْمَدْرَسَةِ) VE OKUL ÇALIŞANLARI</text>\n  <rect x="20" y="46" width="210" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Eğitim ve Araştırma Birimleri</text>\n  <text x="125" y="98" text-anchor="middle" font-size="12" fill="#1e3a8a">• صَفٌّ (Saffun): Sınıf / Derslik</text>\n  <text x="125" y="124" text-anchor="middle" font-size="12" fill="#1e3a8a">• مَكْتَبَةٌ (Mektebetün): Kütüphane</text>\n  <text x="125" y="150" text-anchor="middle" font-size="12" fill="#1e3a8a">• مُخْتَبَرٌ (Muhtebirun): Laboratuvar</text>\n  <text x="125" y="176" text-anchor="middle" font-size="12" fill="#1e3a8a">• مَسْجِدٌ (Mescidün): Mescit</text>\n  <text x="125" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">فِي الْمَدْرَسَةِ مَكْتَبَةٌ وَمُخْتَبَرٌ</text>\n\n  <rect x="245" y="46" width="210" height="194" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">İdari ve Ortak Alanlar</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" fill="#14532d">• غُرْفَةُ الْمُدِيرِ: Müdür Odası</text>\n  <text x="350" y="124" text-anchor="middle" font-size="12" fill="#14532d">• غُرْفَةُ الْمُعَلِّمِينَ: Öğretmenler Odası</text>\n  <text x="350" y="150" text-anchor="middle" font-size="12" fill="#14532d">• مَقْصِفٌ (Maksifun): Kantin</text>\n  <text x="350" y="176" text-anchor="middle" font-size="12" fill="#14532d">• فِنَاءُ الْمَدْرَسَةِ: Okul Bahçesi</text>\n  <text x="350" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">الطُّلَّابُ فِي فِنَاءِ الْمَدْرَسَةِ</text>\n\n  <rect x="470" y="46" width="210" height="194" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Okuldaki Kişiler ve Çalışanlar</text>\n  <text x="575" y="98" text-anchor="middle" font-size="12" fill="#713f12">• مُدِيرٌ / مُدِيرَةٌ: Müdür</text>\n  <text x="575" y="124" text-anchor="middle" font-size="12" fill="#713f12">• مُعَلِّمٌ / مُعَلِّمَةٌ: Öğretmen</text>\n  <text x="575" y="150" text-anchor="middle" font-size="12" fill="#713f12">• طَالِبٌ / طَالِبَةٌ: Öğrenci</text>\n  <text x="575" y="176" text-anchor="middle" font-size="12" fill="#713f12">• مُوَظَّفٌ / بَائِعٌ: Görevli / Kantinci</text>\n  <text x="575" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">رُتْبَةُ الْعِلْمِ أَعْلَى الرُّتَبِ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OKULDA BULUNAN EŞYALAR, SIRA SAYILARI VE YER-YÖN ZARFLARI</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Sınıf ve Okul Eşyaları (أَدَوَاتُ الصَّفِّ)</text>\n  <text x="40" y="98" font-size="12" fill="#831843">• سَبُّورَةٌ ذَكِيَّةٌ (Sebbûretün zekiyyetün): Akıllı tahta</text>\n  <text x="40" y="122" font-size="12" fill="#831843">• مَقْعَدٌ (Mak\'adün): Öğrenci sırası</text>\n  <text x="40" y="146" font-size="12" fill="#831843">• خَرِيطَةٌ (Harîtatün): Harita</text>\n  <text x="40" y="170" font-size="12" fill="#831843">• حَاسُوبٌ (Hâsûbun): Bilgisayar</text>\n  <text x="40" y="194" font-size="12" fill="#831843">• سَاعَةٌ (Sâatün): Saat · مَكْتَبَةٌ: Kitaplık</text>\n  <text x="180" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">أَنَا طَالِبٌ فِي الصَّفِّ السَّادِسِ (6. sınıfta öğrenciyim)</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Sıra Sayıları ve Yer-Yön Zarfları</text>\n  <text x="380" y="98" font-size="11.5" fill="#581c87">• اَلْأَوَّلُ (1.) · اَلثَّانِي (2.) · اَلثَّالِثُ (3.)</text>\n  <text x="380" y="120" font-size="11.5" fill="#581c87">• اَلرَّابِعُ (4.) · اَلْخَامِسُ (5.) · اَلسَّادِسُ (6.)</text>\n  <text x="380" y="142" font-size="11.5" fill="#581c87">• اَلطَّابِقُ الْأَوَّلُ (1. Kat) · اَلطَّابِقُ الثَّانِي (2. Kat)</text>\n  <text x="380" y="168" font-size="11.5" font-weight="bold" fill="#6b21a8">• يَمِينَ (sağında) · يَسَارَ (solunda)</text>\n  <text x="380" y="190" font-size="11.5" font-weight="bold" fill="#6b21a8">• أَمَامَ (önünde) · خَلْفَ (arkasında) · فَوْقَ / تَحْتَ</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">الْمُخْتَبَرُ يَمِينَ الْمَكْتَبَةِ فِي الطَّابِقِ الثَّانِي</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÜNİTE DEĞERLENDİRME: SORU VE CEVAP KALIPLARI</text>\n  <rect x="25" y="48" width="650" height="92" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Bulunma ve Konum Sorma: مَاذَا يُوجَدُ / تُوجَدُ فِي ...؟ — أَيْنَ يُوجَدُ / تُوجَدُ ...؟</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• مَاذَا يُوجَدُ فِي الصَّفِّ؟ ➔ يُوجَدُ فِي الصَّفِّ مَقْعَدٌ وَحَاسُوبٌ وَسَبُّورَةٌ ذَكِيَّةٌ.</text>\n  <text x="350" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">• أَيْنَ تُوجَدُ الْمَكْتَبَةُ؟ ➔ تُوجَدُ الْمَكْتَبَةُ فِي الطَّابِقِ الْأَوَّلِ يَسَارَ غُرْفَةِ الْمُدِيرِ.</text>\n\n  <rect x="25" y="152" width="650" height="90" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">2. Kişilerin Görev Yeri ve Etkinlikleri (الْمُدِيرُ وَالْمُعَلِّمُ وَالطَّالِبُ)</text>\n  <text x="350" y="202" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">• أَيْنَ الْمُدِيرُ؟ ➔ هُوَ فِي غُرْفَةِ الْمُدِيرِ. · أَيْنَ الْمُعَلِّمُ؟ ➔ هُوَ فِي غُرْفَةِ الْمُعَلِّمِينَ.</text>\n  <text x="350" y="226" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">• مَاذَا يَفْعَلُ الطَّالِبُ فِي الْمُخْتَبَرِ؟ ➔ هُوَ يَعْمَلُ تَجْرِبَةً فِي الْمُخْتَبَرِ. (مُمْتَاز! / طَبْعًا!)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
